var firstListItemEl;

function amendBankStatementCopy() {
  firstParaEl = document.querySelector('.container-with-aside__main-content > div > p')
  firstListItemEl = document.querySelector('.feature-list > .feature-list__item:first-child');

  if (firstParaEl) {
   return firstParaEl.innerText = 'Please provide all bank statements received in 2020. We understand that revenues may be down this year.';
  }

  if (firstListItemEl) {
   return firstParaEl.innerHTML = '<strong>Cover all months of 2020 in full with no gaps</strong>, from January to the most recently received.';
  }
}

amendBankStatementCopy();
